    Operator,
    StructuredQuery,
    Visitor,
)


class TencentVectorDBTranslator(Visitor):
    """Translate StructuredQuery to Tencent VectorDB query."""

    COMPARATOR_MAP = {
        Comparator.EQ: "=",
        Comparator.NE: "!=",
        Comparator.GT: ">",
        Comparator.GTE: ">=",
        Comparator.LT: "<",
        Comparator.LTE: "<=",
        Comparator.IN: "in",
        Comparator.NIN: "not in",
